<?php $discount=$context['discount']??null; ?>
<?php if($discount): ?>
<div class="payment-discount-summary" role="status"><span>کد <strong dir="ltr"><?= e($discount['code']) ?></strong> اعمال شده</span><dl><div><dt>مبلغ اولیه</dt><dd><del><?= number_format((int)$discount['original_amount']) ?></del> تومان</dd></div><div><dt>تخفیف</dt><dd><?= number_format((int)$discount['discount_amount']) ?> تومان</dd></div><div><dt>مبلغ نهایی کل</dt><dd><strong><?= number_format((int)$discount['final_amount']) ?> تومان</strong></dd></div></dl>
<?php if(!$context['rows']): ?><form method="post" action="/payments/<?= e($context['type']) ?>/<?= e($context['id']) ?>/discount"><?= csrf_field() ?><input type="hidden" name="remove" value="1"><button class="btn btn--ghost btn--sm">حذف کد تخفیف</button></form><?php else: ?><small><?= $context['parts']===2?'تخفیف این درخواست برای هر دو بخش اقساط حفظ می‌شود.':'تخفیف در مبلغ رسید این درخواست ثبت شده است.' ?></small><?php endif; ?></div>
<?php elseif(!empty($context['couponReady']) && !$context['rows'] && ($context['payable']??true)): ?>
<form class="payment-discount-form" method="post" action="/payments/<?= e($context['type']) ?>/<?= e($context['id']) ?>/discount"><?= csrf_field() ?><label class="form-group"><span class="form-label">کد تخفیف دارید؟</span><input class="form-control" name="code" dir="ltr" maxlength="32" minlength="3" pattern="[A-Za-z0-9_۰-۹٠-٩\-]{3,32}" placeholder="کد تخفیف" autocapitalize="characters" autocomplete="off" required></label><button class="btn btn--secondary">اعمال کد</button><small>پیش از واریز، کد را اعمال کنید و مبلغ نهایی را ببینید. تخفیف اقساط روی کل دوره محاسبه می‌شود.</small></form>
<?php endif; ?>
